record DocState(String text, int caret) { }          // immutable memento

final class Editor {
    private DocState state = new DocState("", 0);
    private final Deque<DocState> undo = new ArrayDeque<>();
    void save() {
        undo.push(state);
        if (undo.size() > 100) undo.removeLast();        // bounded caretaker
    }
    void undo() { if (!undo.isEmpty()) state = undo.pop(); }
    DocState state() { return state; }
}

