UndoManager undoManager = new UndoManager();
undoManager.setLimit(100);
textField.getDocument().addUndoableEditListener(undoManager);

undoManager.undo();          // applies the inverse of the last edit
undoManager.redo();          // re-applies it
// whole-state mementos stay possible: an edit can hold a record snapshot.

static byte[] snapshot(Serializable state) throws IOException {
    var bytes = new ByteArrayOutputStream();
    try (var out = new ObjectOutputStream(bytes)) {
        out.writeObject(state);
    }
    return bytes.toByteArray();          // detached memento
}

static Object restore(byte[] memento) throws IOException, ClassNotFoundException {
    try (var in = new ObjectInputStream(new ByteArrayInputStream(memento))) {
        return in.readObject();
    }
}
